from __future__ import annotations

from tenant_context import TenantContext, is_admin_like, is_read_only


def can_read(ctx: TenantContext) -> tuple[bool, str]:
    if is_read_only(ctx):
        return (True, "ok")
    if ctx.role in {"member", "admin", "owner"}:
        return (True, "ok")
    return (False, "role_not_allowed")


def can_write(ctx: TenantContext) -> tuple[bool, str]:
    if is_read_only(ctx):
        return (False, "readonly_forbidden")
    if is_admin_like(ctx):
        return (True, "ok")
    if ctx.role == "member":
        return (True, "ok")
    return (False, "role_not_allowed")


def can_delete(ctx: TenantContext) -> tuple[bool, str]:
    if is_admin_like(ctx):
        return (True, "ok")
    return (False, "admin_required")


def validate_action_for_role(ctx: TenantContext, action: str) -> tuple[bool, str]:
    key = action.strip().lower()
    if key in {"get_invoice", "list_invoices"}:
        return can_read(ctx)
    if key in {"create_invoice", "mark_paid"}:
        return can_write(ctx)
    if key == "delete_invoice":
        return can_delete(ctx)
    return (False, "invalid_action")


def is_supported_action(action: str) -> bool:
    return action.strip().lower() in {
        "get_invoice",
        "list_invoices",
        "create_invoice",
        "mark_paid",
        "delete_invoice",
    }


def can_manage_billing(ctx: TenantContext) -> tuple[bool, str]:
    if ctx.role in {"owner", "admin"}:
        return (True, "ok")
    return (False, "billing_admin_required")


def action_category(action: str) -> str:
    key = action.strip().lower()
    if key in {"get_invoice", "list_invoices"}:
        return "read"
    if key in {"create_invoice", "mark_paid"}:
        return "write"
    if key == "delete_invoice":
        return "delete"
    return "unknown"

