from __future__ import annotations

from threading import Lock
from typing import Any


class BillingRepository:
    def __init__(self) -> None:
        self._lock = Lock()
        self._records: dict[str, dict[str, dict[str, Any]]] = {}

    def save(self, tenant_id: str, invoice_id: str, payload: dict[str, Any]) -> None:
        tid = tenant_id.strip()
        iid = invoice_id.strip()
        if not tid:
            raise ValueError("tenant_id required")
        if not iid:
            raise ValueError("invoice_id required")
        with self._lock:
            tenant_map = self._records.setdefault(tid, {})
            tenant_map[iid] = dict(payload)

    def get(self, tenant_id: str, invoice_id: str) -> dict[str, Any] | None:
        tid = tenant_id.strip()
        iid = invoice_id.strip()
        if not tid or not iid:
            return None
        with self._lock:
            tenant_map = self._records.get(tid, {})
            item = tenant_map.get(iid)
            return dict(item) if item is not None else None

    def list_for_tenant(self, tenant_id: str) -> list[dict[str, Any]]:
        tid = tenant_id.strip()
        if not tid:
            return []
        with self._lock:
            tenant_map = self._records.get(tid, {})
            return [dict(item) for item in tenant_map.values()]

    def count_for_tenant(self, tenant_id: str) -> int:
        return len(self.list_for_tenant(tenant_id))

    def tenant_ids(self) -> list[str]:
        with self._lock:
            return sorted(self._records.keys())

    def clear(self) -> None:
        with self._lock:
            self._records.clear()

    def snapshot(self) -> dict[str, dict[str, dict[str, Any]]]:
        with self._lock:
            return {
                tenant_id: {invoice_id: dict(value) for invoice_id, value in tenant_map.items()}
                for tenant_id, tenant_map in self._records.items()
            }

    def has_invoice(self, tenant_id: str, invoice_id: str) -> bool:
        return self.get(tenant_id, invoice_id) is not None

    def remove_invoice(self, tenant_id: str, invoice_id: str) -> bool:
        tid = tenant_id.strip()
        iid = invoice_id.strip()
        if not tid or not iid:
            return False
        with self._lock:
            tenant_map = self._records.get(tid)
            if not tenant_map:
                return False
            if iid in tenant_map:
                del tenant_map[iid]
                return True
            return False

