from typing import Any


class EventLog:
    def __init__(self) -> None:
        self._lock = Lock()
        self._events: list[dict[str, Any]] = []

    def add(self, event_type: str, payload: dict[str, Any]) -> None:
        item = {"event_type": event_type.strip() or "unknown", "payload": dict(payload)}
        with self._lock:
            self._events.append(item)

    def list_all(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(item) for item in self._events]

    def by_type(self, event_type: str) -> list[dict[str, Any]]:
        target = event_type.strip()
        with self._lock:
            return [dict(item) for item in self._events if str(item.get("event_type", "")) == target]

    def by_tenant(self, tenant_id: str) -> list[dict[str, Any]]:
        target = tenant_id.strip()
        with self._lock:
            return [
                dict(item)
                for item in self._events
                if str(item.get("payload", {}).get("tenant_id", "")) == target
            ]

    def count(self) -> int:
        with self._lock:
            return len(self._events)

    def clear(self) -> None:
        with self._lock:
            self._events.clear()

    def summary(self) -> dict[str, int]:
        with self._lock:
            out: dict[str, int] = {}
            for item in self._events:
                key = str(item.get("event_type", "unknown"))
                out[key] = out.get(key, 0) + 1
            return out

    def latest(self) -> dict[str, Any] | None:
        with self._lock:
            if not self._events:
                return None
            return dict(self._events[-1])

    def remove_by_type(self, event_type: str) -> int:
        target = event_type.strip()
        with self._lock:
            before = len(self._events)
            self._events = [item for item in self._events if str(item.get("event_type", "")) != target]
            return before - len(self._events)

    def has_event_type(self, event_type: str) -> bool:
        return len(self.by_type(event_type)) > 0

