        self,
        *,
        tenant_id: str,
        actor_id: str,
        role: str,
        request_id: str,
        invoice_id: str,
        amount_cents: int,
    ) -> dict[str, Any]:
        return self.handle(
            {
                "tenant_id": tenant_id,
                "actor_id": actor_id,
                "role": role,
                "request_id": request_id,
                "action": "create_invoice",
                "body": {"invoice_id": invoice_id, "amount_cents": amount_cents},
