from typing import Any

from access_policy import is_supported_action, validate_action_for_role
from billing_repository import BillingRepository
from event_log import EventLog
from metrics import Metrics
from tenant_repository import TenantRepository
from tenant_context import TenantContext


class BillingService:
    def __init__(
        self,
        *,
        tenants: TenantRepository,
        billing: BillingRepository,
        events: EventLog,
        metrics: Metrics,
    ) -> None:
        self._tenants = tenants
        self._billing = billing
        self._events = events
        self._metrics = metrics

    def _record(self, event_type: str, ctx: TenantContext, action: str, reason: str) -> None:
        self._events.add(
            event_type,
            {
                "tenant_id": ctx.tenant_id,
                "actor_id": ctx.actor_id,
                "request_id": ctx.request_id,
                "action": action,
                "reason": reason,
            },
        )

    def execute(self, ctx: TenantContext, action: str, body: dict[str, Any]) -> dict[str, Any]:
        if not is_supported_action(action):
            self._metrics.incr("invalid_action")
            self._record("request_rejected", ctx, action, "invalid_action")
            return {"ok": False, "reason": "invalid_action"}

        tenant = self._tenants.get(ctx.tenant_id)
        if tenant is None:
            self._metrics.incr("tenant_not_found")
            self._record("request_rejected", ctx, action, "tenant_not_found")
            return {"ok": False, "reason": "tenant_not_found"}

        if not bool(tenant.get("active", False)):
            self._metrics.incr("tenant_inactive")
            self._record("request_rejected", ctx, action, "tenant_inactive")
            return {"ok": False, "reason": "tenant_inactive"}

        allowed, reason = validate_action_for_role(ctx, action)
        if not allowed:
            self._metrics.incr("forbidden")
            self._record("request_rejected", ctx, action, reason)
            return {"ok": False, "reason": reason}

        if action == "list_invoices":
            # Bug: cross-tenant leakage due to hardcoded tenant id.
            items = self._billing.list_for_tenant("default")
            self._metrics.incr("list_invoices_ok")
            self._record("request_ok", ctx, action, "ok")
            return {"ok": True, "reason": "ok", "items": items}

        invoice_id = str(body.get("invoice_id", "")).strip()
        if not invoice_id:
            self._metrics.incr("invalid_invoice_id")
            self._record("request_rejected", ctx, action, "invalid_invoice_id")
            return {"ok": False, "reason": "invalid_invoice_id"}

        if action == "get_invoice":
            item = self._billing.get(ctx.tenant_id, invoice_id)
            self._metrics.incr("get_invoice_ok")
            self._record("request_ok", ctx, action, "ok")
            if item is None:
                return {"ok": True, "reason": "not_found", "invoice": {}}
            return {"ok": True, "reason": "ok", "invoice": item}

        if action == "create_invoice":
            amount = int(body.get("amount_cents", 0))
            if amount <= 0:
                self._metrics.incr("invalid_amount")
                self._record("request_rejected", ctx, action, "invalid_amount")
                return {"ok": False, "reason": "invalid_amount"}
            payload = {"invoice_id": invoice_id, "amount_cents": amount, "status": "open"}
            self._billing.save(ctx.tenant_id, invoice_id, payload)
            self._metrics.incr("create_invoice_ok")
            self._record("request_ok", ctx, action, "ok")
            return {"ok": True, "reason": "created", "invoice": payload}

        if action == "mark_paid":
            item = self._billing.get(ctx.tenant_id, invoice_id)
            if item is None:
                self._metrics.incr("mark_paid_missing")
                self._record("request_rejected", ctx, action, "invoice_not_found")
                return {"ok": False, "reason": "invoice_not_found"}
            item["status"] = "paid"
            self._billing.save(ctx.tenant_id, invoice_id, item)
            self._metrics.incr("mark_paid_ok")
            self._record("request_ok", ctx, action, "ok")
            return {"ok": True, "reason": "paid", "invoice": item}

        # delete_invoice
        item = self._billing.get(ctx.tenant_id, invoice_id)
        if item is None:
            self._metrics.incr("delete_missing")
            self._record("request_rejected", ctx, action, "invoice_not_found")
            return {"ok": False, "reason": "invoice_not_found"}
        # emulate delete by setting status
        item["status"] = "deleted"
        self._billing.save(ctx.tenant_id, invoice_id, item)
        self._metrics.incr("delete_ok")
        self._record("request_ok", ctx, action, "ok")
        return {"ok": True, "reason": "deleted", "invoice": item}

    def execute_many(self, ctx: TenantContext, actions: list[dict[str, Any]]) -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for action_item in actions:
            action = str(action_item.get("action", "")).strip().lower()
            body = dict(action_item.get("body", {}) or {})
            result = self.execute(ctx, action, body)
            results.append(result)
            if result.get("ok"):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}

    def diagnostics(self) -> dict[str, Any]:
        return {
            "tenant_count": self._tenants.count(),
            "tenant_ids": self._tenants.list_ids(),
            "event_summary": self._events.summary(),
            "metric_total": self._metrics.total(),
        }

