from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class TenantContext:
    tenant_id: str
    actor_id: str
    role: str
    request_id: str

    def validate(self) -> None:
        if not self.tenant_id.strip():
            raise ValueError("tenant_id required")
        if not self.actor_id.strip():
            raise ValueError("actor_id required")
        if not self.request_id.strip():
            raise ValueError("request_id required")
        if self.role.strip().lower() not in {"owner", "admin", "member", "readonly"}:
            raise ValueError("invalid_role")


def context_from_payload(payload: dict[str, Any]) -> TenantContext:
    ctx = TenantContext(
        tenant_id=str(payload.get("tenant_id", "")).strip(),
        actor_id=str(payload.get("actor_id", "")).strip(),
        role=str(payload.get("role", "member")).strip().lower(),
        request_id=str(payload.get("request_id", "")).strip(),
    )
    ctx.validate()
    return ctx


def is_admin_like(ctx: TenantContext) -> bool:
    return ctx.role in {"owner", "admin"}


def is_read_only(ctx: TenantContext) -> bool:
    return ctx.role == "readonly"


def tag_context(ctx: TenantContext) -> str:
    return f"{ctx.tenant_id}:{ctx.actor_id}:{ctx.role}:{ctx.request_id}"


def context_to_public(ctx: TenantContext) -> dict[str, str]:
    return {
        "tenant_id": ctx.tenant_id,
        "actor_id": ctx.actor_id,
        "role": ctx.role,
        "request_id": ctx.request_id,
    }


def is_owner(ctx: TenantContext) -> bool:
    return ctx.role == "owner"


def is_member(ctx: TenantContext) -> bool:
    return ctx.role == "member"


def role_rank(ctx: TenantContext) -> int:
    ranks = {"readonly": 0, "member": 1, "admin": 2, "owner": 3}
    return ranks.get(ctx.role, -1)

