from __future__ import annotations

from threading import Lock
from typing import Any


class TenantRepository:
    def __init__(self) -> None:
        self._lock = Lock()
        self._tenants: dict[str, dict[str, Any]] = {}

    def seed(self, tenants: list[dict[str, Any]]) -> None:
        with self._lock:
            self._tenants.clear()
            for tenant in tenants:
                tenant_id = str(tenant.get("tenant_id", "")).strip()
                if not tenant_id:
                    raise ValueError("tenant_id required")
                self._tenants[tenant_id] = {
                    "tenant_id": tenant_id,
                    "name": str(tenant.get("name", tenant_id)).strip(),
                    "active": bool(tenant.get("active", True)),
                    "plan": str(tenant.get("plan", "starter")).strip().lower(),
                }

    def get(self, tenant_id: str) -> dict[str, Any] | None:
        key = tenant_id.strip()
        if not key:
            return None
        with self._lock:
            item = self._tenants.get(key)
            return dict(item) if item is not None else None

    def exists(self, tenant_id: str) -> bool:
        return self.get(tenant_id) is not None

    def count(self) -> int:
        with self._lock:
            return len(self._tenants)

    def list_ids(self) -> list[str]:
        with self._lock:
            return sorted(self._tenants.keys())

    def active_tenants(self) -> list[dict[str, Any]]:
        with self._lock:
            return [dict(item) for item in self._tenants.values() if bool(item.get("active", False))]

    def snapshot(self) -> dict[str, dict[str, Any]]:
        with self._lock:
            return {key: dict(value) for key, value in self._tenants.items()}

    def update(self, tenant_id: str, updates: dict[str, Any]) -> bool:
        key = tenant_id.strip()
        if not key:
            return False
        with self._lock:
            current = self._tenants.get(key)
            if current is None:
                return False
            updated = dict(current)
            updated.update(dict(updates))
            self._tenants[key] = updated
            return True

    def deactivate(self, tenant_id: str) -> bool:
        return self.update(tenant_id, {"active": False})

